export const CURIOSITY_WHATIF_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): apa itu rasa ingin tahu, bertanya, mengamati, "bagaimana jika"
{n:1,type:"mcq",micro:"Apa itu rasa ingin tahu",q:"'Rasa ingin tahu' (curiosity) adalah...",options:["Dorongan untuk bertanya, mencari tahu, & memahami hal yang belum kita mengerti","Perasaan bosan pada semua hal","Keinginan untuk selalu benar"],answer:0,explain:"Rasa ingin tahu adalah mesin belajar: ia membuat kita bertanya 'kenapa' & 'bagaimana jika', lalu mencari jawabannya.",hint:"Ingin mencari tahu, atau ingin selalu benar?"},
{n:2,type:"mcq",micro:"Tanda rasa ingin tahu",q:"Contoh sikap ingin tahu saat melihat sesuatu yang aneh:",options:["Marah karena tidak paham","Mengabaikannya karena bukan urusanku","Bertanya 'kok bisa begitu ya?' lalu mencoba mencari tahu"],answer:1,explain:"Orang yang ingin tahu berhenti sejenak pada hal aneh & bertanya, bukan langsung melewatinya.",hint:"Bertanya & cari tahu, atau abaikan?"},
{n:3,type:"mcq",micro:"Pertanyaan 'bagaimana jika'",q:"Pertanyaan 'Bagaimana jika...' berguna untuk...",options:["Menyalahkan orang lain","Menghafal fakta","Membayangkan kemungkinan baru & ide yang belum ada"],answer:2,explain:"'Bagaimana jika sepeda bisa terbang?' membuka pikiran ke ide baru. Ini alat utama berpikir kreatif.",hint:"Membayangkan kemungkinan, atau menghafal?"},
{n:4,type:"mcq",micro:"Pertanyaan terbuka vs tertutup",q:"Manakah pertanyaan TERBUKA (jawabannya bisa panjang & beragam)?",options:["'Apa yang membuat langit terlihat biru?'","'Apakah langit berwarna biru?'","'Langit biru, kan?'"],answer:0,explain:"Pertanyaan terbuka (apa, mengapa, bagaimana) memancing penjelasan. Pertanyaan tertutup hanya minta 'ya/tidak'.",hint:"Jawabannya 'ya/tidak', atau penjelasan panjang?"},
{n:5,type:"mcq",micro:"Mengamati dulu",q:"Sebelum bertanya yang bagus, langkah yang membantu adalah...",options:["Menunggu orang lain menjelaskan","Mengamati dengan teliti: apa yang benar-benar terjadi, apa yang berubah, apa yang janggal","Langsung menebak jawaban"],answer:1,explain:"Pengamatan yang cermat memunculkan pertanyaan yang tajam. 'Kenapa daun ini menguning hanya di ujungnya?'",hint:"Amati dulu, atau tebak langsung?"},
{n:6,type:"mcq",micro:"Rasa ingin tahu & belajar",q:"Kenapa rasa ingin tahu membantu kita belajar lebih cepat?",options:["Karena guru memberi nilai lebih","Tidak ada hubungannya dengan belajar","Karena kita jadi ingat lebih baik hal yang benar-benar kita ingin tahu jawabannya"],answer:2,explain:"Otak menyimpan lebih kuat informasi yang kita cari karena penasaran, dibanding yang dipaksa dihafal.",hint:"Lebih ingat kalau penasaran, atau tidak berhubungan?"},
{n:7,type:"mcq",micro:"Bertanya bukan tanda bodoh",q:"Anggapan 'kalau bertanya berarti bodoh' itu...",options:["Keliru — bertanya adalah cara orang pintar mengisi hal yang belum ia tahu","Benar, sebaiknya diam saja","Benar untuk anak besar"],answer:0,explain:"Orang yang paling banyak tahu biasanya paling banyak bertanya. Diam karena malu justru menghambat belajar.",hint:"Bertanya = mengisi yang belum tahu, atau tanda bodoh?"},
{n:8,type:"mcq",micro:"Sumber rasa ingin tahu",q:"Rasa ingin tahu sering muncul saat...",options:["Kita sudah tahu semua jawaban","Ada kejutan, keanehan, atau sesuatu yang tidak sesuai dugaan kita","Semua berjalan seperti biasa & membosankan"],answer:1,explain:"Otak 'terbangun' saat menemukan hal yang tidak terduga. Kejutan adalah pintu masuk rasa ingin tahu.",hint:"Saat ada kejutan, atau saat semua biasa saja?"},
{n:9,type:"order",micro:"Alur rasa ingin tahu",q:"Urutkan alur alami saat rasa ingin tahu bekerja.",items:["Memperhatikan sesuatu yang menarik atau janggal","Mengajukan pertanyaan tentang hal itu","Mencari tahu (mengamati, mencoba, bertanya, membaca)","Menemukan jawaban & memunculkan pertanyaan baru"],answer:[0,1,2,3],explain:"Perhatikan → tanya → cari tahu → jawaban + pertanyaan baru. Siklus ini berputar terus.",hint:"Apa yang datang sebelum bertanya?"},
{n:10,type:"mcq",micro:"'Bagaimana jika' pada benda biasa",q:"Kamu melihat gelas. Pertanyaan 'bagaimana jika' yang membuka ide:",options:["'Ini gelas.'","'Gelas untuk minum.'","'Bagaimana jika gelas ini punya dua dasar?' atau 'Bagaimana jika terbuat dari es?'"],answer:2,explain:"'Bagaimana jika' mengubah sesuatu yang biasa & memaksa kita membayangkan akibatnya — awal dari ide baru.",hint:"Mengubah & membayangkan, atau menyebut fakta?"},
{n:11,type:"tf",micro:"Rasa ingin tahu bisa dilatih",q:"Benar atau Salah: Rasa ingin tahu adalah kebiasaan yang bisa dilatih, bukan bakat yang dimiliki sebagian orang saja.",answer:true,explain:"Dengan rutin bertanya 'kenapa' & 'bagaimana jika', siapa pun bisa menumbuhkan rasa ingin tahu yang kuat.",hint:"Bisa dilatih, atau bakat tetap?"},
{n:12,type:"tf",micro:"Satu pertanyaan cukup?",q:"Benar atau Salah: Untuk memahami sesuatu dengan baik, biasanya cukup satu pertanyaan saja.",answer:false,explain:"Sebaliknya, pemahaman yang dalam butuh serangkaian pertanyaan yang saling menyambung, satu jawaban memunculkan pertanyaan berikutnya.",hint:"Cukup satu, atau berangkai?"},
{n:13,type:"mcq",micro:"Menahan diri dari 'sudah tahu'",q:"Sikap yang mematikan rasa ingin tahu:",options:["Buru-buru berkata 'ah, aku sudah tahu itu' sebelum benar-benar memeriksa","Bertanya lebih lanjut","Mengakui 'aku belum yakin'"],answer:0,explain:"Merasa 'sudah tahu' menutup pintu belajar. Orang yang ingin tahu tetap memeriksa, meski merasa familiar.",hint:"'Sudah tahu' cepat, atau tetap memeriksa?"},
{n:14,type:"mcq",micro:"Rasa ingin tahu vs kepo negatif",q:"Beda rasa ingin tahu yang sehat dengan 'kepo' yang mengganggu:",options:["Rasa ingin tahu sehat berarti menanyakan semua hal ke semua orang","Rasa ingin tahu sehat menghormati batas & privasi orang; kepo yang buruk mengorek urusan pribadi orang tanpa izin","Keduanya sama saja"],answer:1,explain:"Ingin tahu tentang cara kerja dunia itu sehat. Mengorek rahasia pribadi orang tanpa izin bukan rasa ingin tahu yang baik.",hint:"Menghormati batas, atau mengorek tanpa izin?"},
{n:15,type:"mcq",micro:"Mencatat pertanyaan",q:"Kenapa berguna mencatat pertanyaan yang muncul di kepala?",options:["Supaya terlihat rajin","Tidak berguna, pertanyaan sebaiknya dilupakan","Supaya tidak lupa & bisa dicari jawabannya nanti saat ada waktu"],answer:2,explain:"'Buku pertanyaan' menyimpan rasa penasaran. Banyak penemu punya kebiasaan ini.",hint:"Simpan untuk dicari nanti, atau lupakan?"},
{n:16,type:"tf",micro:"Pertanyaan 'bodoh'",q:"Benar atau Salah: Pertanyaan yang terdengar sederhana atau 'mendasar' sering justru membuka pemahaman penting.",answer:true,explain:"'Kenapa langit biru?' terdengar sederhana tapi jawabannya menjelaskan cahaya & atmosfer. Pertanyaan dasar itu berharga.",hint:"Membuka pemahaman, atau buang waktu?"},
{n:17,type:"mcq",micro:"Rasa ingin tahu pada kesalahan",q:"Kamu salah menjawab soal. Sikap ingin tahu:",options:["'Menarik, di mana ya letak kekeliruanku? Coba kutelusuri.'","'Ah sudahlah, aku memang tidak bisa.'","Menyalin jawaban teman tanpa memahami"],answer:0,explain:"Kesalahan adalah petunjuk. Orang yang ingin tahu memeriksa kesalahannya, bukan menghindarinya.",hint:"Telusuri kekeliruan, atau menyerah?"},
{n:18,type:"mcq",micro:"Bertanya ke diri sendiri",q:"Saat membaca sesuatu yang baru, pertanyaan yang baik untuk diri sendiri:",options:["Tidak perlu bertanya apa-apa","'Apa maksudnya ini? Bagaimana kaitannya dengan yang sudah kutahu? Apa yang masih membingungkan?'","'Kapan ini selesai?'"],answer:1,explain:"Bertanya pada diri sendiri saat belajar membuat kita membaca aktif, bukan sekadar melewati kata.",hint:"Menghubungkan & memeriksa paham, atau menunggu selesai?"},
{n:19,type:"mcq",micro:"Rasa ingin tahu & penemuan",q:"Banyak penemuan besar berawal dari...",options:["Kebetulan tanpa ada yang bertanya apa pun","Perintah untuk menemukan sesuatu","Seseorang memperhatikan hal kecil yang aneh & bertanya 'kenapa begitu?'"],answer:2,explain:"Penisilin, Velcro, & banyak lainnya lahir karena seseorang penasaran pada 'kecelakaan kecil' yang aneh.",hint:"Memperhatikan & bertanya, atau kebetulan murni?"},
{n:20,type:"open",micro:"Daftar 'bagaimana jika'",q:"Pilih satu benda di sekitarmu (misalnya sepatu, pintu, sendok). Tulis 5 pertanyaan 'Bagaimana jika...' tentang benda itu, lalu pilih satu yang menurutmu paling menarik & jelaskan kenapa.",sample:"Benda: sendok. (1) Bagaimana jika sendok bisa mengubah rasa makanan jadi lebih manis? (2) Bagaimana jika sendok terbuat dari bahan yang bisa dimakan? (3) Bagaimana jika sendok punya sensor yang memberi tahu suhu makanan? (4) Bagaimana jika satu sendok bisa berubah ukuran sesuai kebutuhan? (5) Bagaimana jika sendok bisa melipat jadi sekecil kartu untuk dibawa? Yang paling menarik: nomor 2, sendok yang bisa dimakan, karena bisa mengurangi sampah plastik sekali pakai di kantin & acara besar, dan itu masalah nyata yang sering kulihat.",explain:"Jawaban baik: 5 pertanyaan 'bagaimana jika' yang benar-benar mengubah sesuatu dari benda itu (bukan sekadar mendeskripsikannya), lalu satu pilihan dengan alasan yang masuk akal (menarik, berguna, atau memecahkan masalah nyata).",hint:"Ubah satu sifat benda tiap pertanyaan: bahan, ukuran, fungsi, bentuk, atau kemampuannya."},

// FASE B — PEMAHAMAN (21-40): jenis pertanyaan, menahan penilaian, asumsi, mengapa penting
{n:21,type:"classify",micro:"Pertanyaan terbuka vs tertutup",q:"Kelompokkan tiap pertanyaan ke 'Terbuka' (memancing penjelasan) atau 'Tertutup' (jawaban ya/tidak/satu kata).",items:["Mengapa air laut terasa asin?","Apakah air laut asin?","Bagaimana cara burung tahu arah saat bermigrasi?","Apakah burung bermigrasi?"],groups:["Terbuka","Tertutup"],answer:{"Terbuka":["Mengapa air laut terasa asin?","Bagaimana cara burung tahu arah saat bermigrasi?"],"Tertutup":["Apakah air laut asin?","Apakah burung bermigrasi?"]},explain:"Terbuka: 'mengapa', 'bagaimana', 'apa yang' — minta penjelasan. Tertutup: 'apakah' — minta ya/tidak.",hint:"Bisa dijawab 'ya' saja, atau butuh penjelasan?"},
{n:22,type:"mcq",micro:"Menahan penilaian",q:"Saat menampung ide-ide baru, kenapa penting menunda berkata 'itu tidak mungkin'?",options:["Karena penilaian terlalu cepat mematikan ide yang mungkin bisa dikembangkan jadi bagus","Karena semua ide pasti bagus","Karena kita tidak boleh berpikir kritis sama sekali"],answer:0,explain:"Ide mentah sering terdengar aneh. Menilai terlalu dini menghentikannya sebelum sempat tumbuh. Kritik datang belakangan.",hint:"Beri ide waktu tumbuh, atau semua ide pasti bagus?"},
{n:23,type:"mcq",micro:"Apa itu asumsi",q:"'Asumsi' adalah...",options:["Pertanyaan yang bagus","Sesuatu yang kita anggap benar tanpa memeriksanya lebih dulu","Fakta yang sudah dibuktikan"],answer:1,explain:"Contoh asumsi: 'jam harus bulat'. Menyadari & menantang asumsi membuka ide baru: jam bisa berbentuk apa saja.",hint:"Dianggap benar tanpa diperiksa, atau sudah dibuktikan?"},
{n:24,type:"mcq",micro:"Menantang asumsi",q:"Toko roti selalu buka pagi. Pertanyaan yang menantang asumsi:",options:["'Jam berapa toko roti buka?'","'Roti apa yang dijual?'","'Kenapa harus pagi? Bagaimana jika ada toko roti yang justru buka malam?'"],answer:2,explain:"Menantang asumsi 'harus pagi' bisa memunculkan ide bisnis baru: roti hangat untuk orang yang pulang kerja malam.",hint:"Mempertanyakan 'kenapa harus begitu', atau menanyakan detail biasa?"},
{n:25,type:"mcq",micro:"Rasa ingin tahu & empati",q:"Bagaimana rasa ingin tahu membantu memahami orang lain?",options:["Membuat kita bertanya 'kenapa dia berpikir begitu?' alih-alih langsung menilai","Membuat kita mengabaikan pendapat orang lain","Tidak ada hubungannya"],answer:0,explain:"Ingin tahu tentang alasan orang lain = pintu ke empati & ke ide yang mempertimbangkan banyak sudut pandang.",hint:"Bertanya alasan orang, atau langsung menilai?"},
{n:26,type:"mcq",micro:"Lima Mengapa",q:"Teknik 'Lima Mengapa' berarti...",options:["Menjawab dengan 5 alasan","Bertanya 'mengapa' berulang kali (sekitar 5x) untuk menembus dari gejala ke akar sebab","Bertanya 5 pertanyaan berbeda sekaligus"],answer:1,explain:"'Kenapa lampu mati?' → sekring putus → beban berlebih → terlalu banyak alat → tidak ada aturan pemakaian. Akarnya ketemu.",hint:"'Mengapa' berulang untuk cari akar, atau 5 pertanyaan acak?"},
{n:27,type:"tf",micro:"Ide pertama = ide terbaik?",q:"Benar atau Salah: Ide pertama yang muncul biasanya sudah merupakan ide terbaik, jadi tidak perlu mencari alternatif.",answer:false,explain:"Sebaliknya, ide pertama sering yang paling jelas & biasa. Ide yang lebih segar biasanya muncul setelah kita memaksakan diri melewati beberapa ide awal.",hint:"Ide pertama cukup, atau teruskan mencari?"},
{n:28,type:"tf",micro:"Bosan & rasa ingin tahu",q:"Benar atau Salah: Rasa bosan tidak pernah berguna & tidak ada kaitannya dengan rasa ingin tahu.",answer:false,explain:"Sebaliknya, bosan yang disikapi dengan 'apa yang bisa kupelajari atau coba sekarang?' bisa berubah jadi bahan bakar rasa ingin tahu.",hint:"Sinyal untuk mencari hal baru, atau selalu buruk?"},
{n:29,type:"mcq",micro:"Pertanyaan yang menggerakkan",q:"Manakah pertanyaan yang paling mungkin memicu ide baru untuk masalah 'sampah plastik di sekolah'?",options:["'Berapa banyak plastik yang dibuang?'","'Siapa yang membuang plastik?'","'Bagaimana jika sampah plastik justru jadi sesuatu yang berharga di sekolah kita?'"],answer:2,explain:"Pertanyaan 'bagaimana jika ... jadi berharga' membalik masalah & memancing ide (bank sampah, kerajinan, tukar poin).",hint:"Membalik masalah jadi peluang, atau sekadar menghitung?"},
{n:30,type:"order",micro:"Dari penasaran ke ide",q:"Urutkan langkah mengubah rasa penasaran jadi ide yang bisa dicoba.",items:["Perhatikan sesuatu yang mengganggu atau menarik perhatianmu","Ajukan beberapa pertanyaan 'kenapa' & 'bagaimana jika'","Kumpulkan banyak kemungkinan jawaban/ide tanpa menilai dulu","Pilih satu ide yang menarik & masuk akal untuk dicoba"],answer:[0,1,2,3],explain:"Perhatikan → tanya → kumpulkan ide → pilih untuk dicoba. Menilai dilakukan setelah ide terkumpul, bukan sebelum.",hint:"Kapan menilai ide, di awal atau setelah terkumpul?"},
{n:31,type:"mcq",micro:"Rasa ingin tahu yang jujur",q:"Bertanya dengan tulus berbeda dari 'pura-pura bertanya' karena...",options:["Kita benar-benar terbuka pada jawaban yang mungkin mengubah pikiran kita","Kita sudah menyiapkan jawaban & hanya ingin didengar","Kita ingin membuat orang lain terlihat salah"],answer:0,explain:"Pertanyaan tulus siap menerima jawaban tak terduga. 'Pertanyaan jebakan' bukan rasa ingin tahu, melainkan debat terselubung.",hint:"Terbuka pada jawaban, atau sudah punya kesimpulan?"},
{n:32,type:"tf",micro:"Rasa ingin tahu perlu waktu",q:"Benar atau Salah: Menyisihkan waktu khusus untuk mengeksplorasi pertanyaan (bukan hanya saat ada tugas) memperkuat kebiasaan ingin tahu.",answer:true,explain:"Seperti otot, rasa ingin tahu tumbuh bila rutin dilatih, misalnya 10 menit sehari menelusuri satu pertanyaan.",hint:"Latihan rutin memperkuat, atau tidak berpengaruh?"},
{n:33,type:"mcq",micro:"Mengubah 'tidak bisa' jadi pertanyaan",q:"Ubah kalimat 'Kita tidak bisa membuat taman di atap' jadi pertanyaan yang membuka ide:",options:["'Siapa yang bilang mau bikin taman?'","'Bagaimana caranya kita bisa membuat taman di atap meski ada keterbatasan?'","'Memang tidak bisa, sudah jelas.'"],answer:1,explain:"Mengubah pernyataan buntu jadi 'bagaimana caranya...' memaksa otak mencari jalan, bukan berhenti.",hint:"'Bagaimana caranya kita bisa...', atau menutup pembicaraan?"},
{n:34,type:"mcq",micro:"Rasa ingin tahu lintas bidang",q:"Kenapa orang kreatif sering tertarik pada banyak bidang berbeda (seni, sains, sejarah, masak)?",options:["Karena mereka tidak bisa fokus","Karena bidang-bidang itu sebenarnya sama saja","Karena ide baru sering muncul dari menggabungkan hal dari bidang yang berbeda"],answer:2,explain:"Menyilangkan ide dari bidang jauh (mis. sarang lebah → desain bangunan hemat bahan) menghasilkan terobosan.",hint:"Menggabungkan bidang berbeda, atau tidak bisa fokus?"},
{n:35,type:"mcq",micro:"Pertanyaan 'apa lagi'",q:"Setelah menemukan satu jawaban, pertanyaan ingin tahu yang lanjut:",options:["'Apa lagi yang mungkin? Apa yang belum kupertimbangkan?'","'Ya sudah, selesai.'","'Aku tidak mau tahu lebih.'"],answer:0,explain:"'Apa lagi?' menjaga eksplorasi tetap terbuka & sering memunculkan jawaban kedua yang lebih baik.",hint:"Terus menggali, atau berhenti di jawaban pertama?"},
{n:36,type:"mcq",micro:"Rasa ingin tahu & rasa takut",q:"Kadang kita menahan pertanyaan karena takut terlihat bodoh. Cara sehat menyikapinya:",options:["Hanya bertanya kalau dipaksa","Ingat bahwa pertanyaanku mungkin juga jadi pertanyaan orang lain yang diam, & bertanya tetap lebih baik daripada tidak paham","Tidak pernah bertanya apa pun"],answer:1,explain:"Keberanian bertanya adalah bagian dari rasa ingin tahu. Sering orang lain berterima kasih karena kita menanyakannya.",hint:"Bertanya tetap lebih baik, atau diam saja aman?"},
{n:37,type:"tf",micro:"Semua pertanyaan sama nilainya?",q:"Benar atau Salah: Semua pertanyaan sama bergunanya; tidak ada yang namanya pertanyaan yang lebih tajam atau lebih membuka.",answer:false,explain:"Sebaliknya, pertanyaan terbuka yang menyentuh 'kenapa' & 'bagaimana jika' biasanya membuka lebih banyak pemikiran daripada pertanyaan ya/tidak.",hint:"Semua sama, atau ada yang lebih membuka?"},
{n:38,type:"mcq",micro:"Menyimpan rasa kagum",q:"Orang yang tetap 'mudah kagum' pada hal-hal biasa (pelangi, semut bekerja, lampu menyala) cenderung...",options:["Kekanak-kanakan & tidak serius","Tidak bisa berpikir dewasa","Lebih sering bertanya & menemukan ide karena tidak menganggap dunia sudah 'selesai dipahami'"],answer:2,explain:"Rasa kagum menjaga pintu pertanyaan tetap terbuka. Menganggap semua 'biasa saja' menutupnya.",hint:"Menjaga pertanyaan terbuka, atau tanda tidak dewasa?"},
{n:39,type:"mcq",micro:"Pertanyaan gabungan",q:"'Bagaimana jika perpustakaan juga berfungsi seperti taman?' adalah contoh pertanyaan yang...",options:["Menggabungkan dua hal berbeda untuk memancing ide baru","Tidak masuk akal & tidak berguna","Hanya soal perpustakaan"],answer:0,explain:"Menggabungkan 'perpustakaan' + 'taman' bisa memunculkan ide: ruang baca terbuka hijau, rak di bawah pohon.",hint:"Menggabungkan dua hal, atau soal satu hal saja?"},
{n:40,type:"open",micro:"Membongkar asumsi",q:"Pikirkan tentang 'tas sekolah'. Tulis 3 asumsi yang biasanya orang anggap benar tentang tas sekolah (misalnya 'harus dipakai di punggung'). Untuk tiap asumsi, tulis satu pertanyaan 'bagaimana jika' yang menantangnya.",sample:"Asumsi 1: Tas harus dipakai di punggung. Bagaimana jika tas sekolah bisa berubah jadi meja lipat kecil saat di kelas? Asumsi 2: Tas terbuat dari kain & harus dibeli. Bagaimana jika tas dibuat dari bahan daur ulang yang dirakit sendiri oleh siswa? Asumsi 3: Isi tas dibawa ke mana-mana setiap hari. Bagaimana jika sekolah punya loker pintar sehingga buku berat tidak perlu dibawa pulang-pergi & tas jadi jauh lebih ringan? Menantang asumsi ketiga membuatku sadar masalah sebenarnya mungkin bukan tasnya, tapi beban yang harus dibawa.",explain:"Jawaban baik: 3 asumsi yang memang biasanya tidak dipertanyakan (bentuk, bahan, cara pakai, isi), masing-masing dipasangkan dengan pertanyaan 'bagaimana jika' yang benar-benar mengubah asumsi itu, bukan sekadar variasi kecil.",hint:"Asumsi = hal yang dianggap 'sudah pasti begitu'. Tanyakan 'kenapa harus begitu?' untuk tiap bagian tas."},

// FASE C — PENERAPAN (41-60): teknik menghasilkan pertanyaan & "bagaimana jika"
{n:41,type:"mcq",micro:"Teknik pembalikan",q:"'Pembalikan' untuk memancing ide berarti...",options:["Menjawab semua dengan 'tidak'","Membalik masalah: alih-alih 'bagaimana membuat kelas lebih tenang', tanya 'bagaimana membuat kelas SANGAT ribut' lalu balik jawabannya","Membalik badan"],answer:1,explain:"Memikirkan cara membuat masalah lebih parah lalu membalik tiap poin sering memunculkan solusi yang tak terpikir.",hint:"Membalik masalah lalu membalik jawabannya, atau menolak semua?"},
{n:42,type:"mcq",micro:"Bertanya dari sudut pengguna",q:"Untuk memperbaiki taman bermain, pertanyaan ingin tahu yang berpusat pada pemakainya:",options:["'Berapa biaya cat pagar?'","'Siapa yang membangun taman ini dulu?'","'Apa yang paling menyenangkan & paling menjengkelkan bagi anak-anak yang bermain di sini?'"],answer:2,explain:"Pertanyaan yang menggali pengalaman pengguna membuka kebutuhan nyata, dasar dari ide yang berguna.",hint:"Pengalaman pemakai, atau detail administratif?"},
{n:43,type:"mcq",micro:"Bertanya 'bagaimana jika tidak ada'",q:"'Bagaimana jika tidak ada listrik selama seminggu di sekolah?' berguna untuk...",options:["Memunculkan ide-ide bertahan & solusi alternatif yang biasanya tidak terpikir","Menakut-nakuti orang","Tidak ada gunanya"],answer:0,explain:"Menghapus sesuatu yang dianggap pasti ada memaksa kita menemukan cara lain, sumber kreativitas yang kuat.",hint:"Memunculkan solusi alternatif, atau menakuti?"},
{n:44,type:"mcq",micro:"Pertanyaan skala",q:"'Bagaimana jika kelas kita 10x lebih besar?' atau '10x lebih kecil?' adalah teknik...",options:["Membandingkan dua kelas","Mengubah skala secara ekstrem untuk melihat ide & masalah baru yang muncul","Mengukur ruang kelas"],answer:1,explain:"Membesar-kecilkan sesuatu secara ekstrem mengungkap hal yang tersembunyi di ukuran normal.",hint:"Mengubah skala ekstrem, atau sekadar mengukur?"},
{n:45,type:"tf",micro:"Kuantitas ide dulu",q:"Benar atau Salah: Saat melatih 'bagaimana jika', menghasilkan banyak pertanyaan liar dulu lebih berguna daripada langsung mencari yang 'benar'.",answer:true,explain:"Banyak pertanyaan = lebih besar peluang ada yang membuka ide bagus. Menyaring dilakukan setelahnya.",hint:"Banyak dulu lalu saring, atau cari yang benar sejak awal?"},
{n:46,type:"mcq",micro:"Menggabungkan acak",q:"Kamu ambil dua kata acak: 'payung' & 'lampu'. Cara memakainya untuk memancing ide:",options:["Membuang salah satu kata","Menyatakan keduanya tidak berhubungan","Tanya 'bagaimana jika payung & lampu jadi satu?' → payung dengan lampu di ujung untuk jalan gelap saat hujan"],answer:2,explain:"Memaksa dua hal tak berhubungan bertemu adalah cara cepat menembus pikiran yang macet.",hint:"Paksa keduanya bertemu, atau buang salah satu?"},
{n:47,type:"mcq",micro:"Pertanyaan 'untuk siapa lagi'",q:"Sebuah alat bantu jalan untuk lansia. Pertanyaan yang memperluas ide:",options:["'Untuk siapa lagi ini bisa berguna? Anak cedera? Petugas yang membawa barang berat?'","'Warnanya apa?'","'Kapan selesai dibuat?'"],answer:0,explain:"Bertanya 'untuk siapa lagi' sering mengungkap pemakai baru & membuat ide lebih bernilai.",hint:"Memperluas pemakai, atau menanyakan detail kecil?"},
{n:48,type:"mcq",micro:"Rasa ingin tahu terarah",q:"Saat waktu terbatas, rasa ingin tahu yang produktif berarti...",options:["Berhenti bertanya sama sekali","Memilih beberapa pertanyaan paling penting untuk masalah yang sedang dihadapi, lalu menggalinya dalam","Mengejar setiap pertanyaan yang lewat tanpa arah"],answer:1,explain:"Rasa ingin tahu tetap butuh fokus: pilih pertanyaan yang paling menggerakkan, telusuri tuntas.",hint:"Fokus ke yang penting, atau kejar semua tanpa arah?"},
{n:49,type:"mcq",micro:"Bertanya pada ahli",q:"Cara ingin tahu yang baik saat bertanya ke orang yang lebih tahu:",options:["Minta ia menjelaskan 'semuanya dari awal'","Tidak menyiapkan apa pun & berharap ia bercerita sendiri","Siapkan pertanyaan spesifik, dengarkan baik-baik, & tanyakan lanjutan berdasarkan jawabannya"],answer:2,explain:"Pertanyaan spesifik + mendengarkan aktif membuat percakapan menggali dalam, bukan mengambang.",hint:"Spesifik & mendengarkan lanjutan, atau minta 'semuanya'?"},
{n:50,type:"order",micro:"Sesi 'bagaimana jika'",q:"Urutkan langkah sesi 'bagaimana jika' untuk sebuah masalah.",items:["Tuliskan masalahnya dalam satu kalimat yang jelas","Buat sebanyak mungkin pertanyaan 'bagaimana jika' dalam 5 menit tanpa menilai","Tandai 2-3 pertanyaan yang paling memancing rasa penasaran","Kembangkan tiap pertanyaan terpilih jadi beberapa ide konkret"],answer:[0,1,2,3],explain:"Perjelas masalah → banjir pertanyaan → pilih yang paling hidup → ubah jadi ide. Menilai selalu setelah, bukan saat, menghasilkan.",hint:"Menilai pertanyaan dilakukan di langkah ke berapa?"},
{n:51,type:"mcq",micro:"Menunda 'ya, tapi'",q:"Dalam sesi ide, mengganti 'Ya, tapi...' dengan 'Ya, dan...' berguna karena...",options:["'Ya, dan' membangun di atas ide orang lain; 'Ya, tapi' langsung mematahkannya","Tidak ada bedanya","'Ya, tapi' lebih sopan"],answer:0,explain:"'Ya, dan' menjaga aliran ide. Fase kritik ('ya, tapi') penting juga, tapi dilakukan terpisah, setelahnya.",hint:"Membangun di atas ide, atau langsung mematahkan?"},
{n:52,type:"tf",micro:"Pertanyaan liar berguna",q:"Benar atau Salah: Pertanyaan yang terdengar mustahil seperti 'bagaimana jika manusia bisa berfotosintesis?' tetap berguna karena bisa memancing ide yang bisa dipakai (mis. pakaian yang menyerap energi matahari).",answer:true,explain:"Ide mustahil sering mengandung 'benih' yang bisa dipindahkan ke solusi nyata. Jangan buru-buru membuangnya.",hint:"Bisa memancing ide nyata, atau buang saja?"},
{n:53,type:"mcq",micro:"Rasa ingin tahu pada penolakan",q:"Idemu ditolak guru. Respons ingin tahu:",options:["Diam & tidak pernah usul lagi","'Boleh saya tahu bagian mana yang jadi masalah? Supaya saya bisa memperbaikinya.'","'Berarti ide saya jelek.'"],answer:1,explain:"Menanyakan alasan penolakan mengubah 'kegagalan' jadi informasi untuk versi berikutnya.",hint:"Tanya bagian yang bermasalah, atau berhenti mencoba?"},
{n:54,type:"mcq",micro:"Meniru dari alam",q:"'Bagaimana cara alam menyelesaikan masalah ini?' adalah pertanyaan yang...",options:["Tidak relevan untuk masalah buatan manusia","Hanya untuk pelajaran biologi","Sering memberi ide desain (mis. duri tanaman → perekat, sirip ikan → kipas hemat energi)"],answer:2,explain:"Alam sudah 'menguji' solusi selama jutaan tahun. Menirunya (biomimikri) adalah sumber ide yang kaya.",hint:"Sumber ide desain, atau cuma untuk biologi?"},
{n:55,type:"mcq",micro:"Pertanyaan pembatas",q:"'Bagaimana jika kita hanya boleh memakai barang bekas untuk proyek ini?' Batasan seperti ini...",options:["Sering justru memicu kreativitas karena memaksa kita mencari cara di luar kebiasaan","Selalu menghambat & sebaiknya dihindari","Membuat proyek jadi tidak mungkin"],answer:0,explain:"Batasan yang tepat mempersempit ruang sehingga otak berhenti memilih jawaban biasa & mulai berkreasi.",hint:"Memicu kreativitas, atau selalu menghambat?"},
{n:56,type:"tf",micro:"Rasa ingin tahu & mendengarkan",q:"Benar atau Salah: Orang yang benar-benar ingin tahu justru menjadi pendengar yang buruk karena sibuk menyiapkan pertanyaan berikutnya.",answer:false,explain:"Sebaliknya, orang yang ingin tahu biasanya pendengar yang lebih baik: mereka mendengarkan untuk memahami & bertanya lanjutan, bukan sekadar menunggu giliran bicara.",hint:"Pendengar lebih baik, atau tidak berhubungan?"},
{n:57,type:"mcq",micro:"Bertanya 'apa yang sebenarnya dibutuhkan'",q:"Seseorang minta 'bor listrik yang lebih kuat'. Pertanyaan ingin tahu yang menggali kebutuhan asli:",options:["'Kenapa tidak beli saja?'","'Untuk apa bornya? Mungkin yang dibutuhkan sebenarnya adalah lubang yang rapi, bukan bor yang kuat.'","'Merek apa yang kamu mau?'"],answer:1,explain:"Menggali 'untuk apa' sering mengungkap kebutuhan sebenarnya (lubang, bukan bor), membuka solusi lain.",hint:"Menggali tujuan sebenarnya, atau menanyakan merek?"},
{n:58,type:"mcq",micro:"Jurnal rasa ingin tahu",q:"Kebiasaan harian yang memperkuat rasa ingin tahu:",options:["Menonton video sampai ketiduran","Menghindari hal-hal baru","Menulis satu 'hal yang aku perhatikan hari ini & satu pertanyaan tentangnya' setiap malam"],answer:2,explain:"Latihan kecil & rutin ('perhatikan + tanya') membuat pikiran otomatis mencari hal menarik sepanjang hari.",hint:"Latihan kecil rutin, atau menghindari hal baru?"},
{n:59,type:"mcq",micro:"Pertanyaan 'kenapa ini masih begini'",q:"Melihat antrean panjang di kantin setiap hari, pertanyaan yang membuka perbaikan:",options:["'Kenapa antrean ini masih terjadi setiap hari? Bagian mana yang paling lambat?'","'Kenapa aku sial harus antre?'","'Antre memang begitu, tidak bisa diubah.'"],answer:0,explain:"Menolak menerima 'memang begitu' & bertanya di mana titik lambatnya adalah awal dari solusi nyata.",hint:"Mencari titik lambat, atau menerima begitu saja?"},
{n:60,type:"open",micro:"Rancang pertanyaan untuk masalah nyata",q:"Pilih satu hal di sekolah atau rumahmu yang menurutmu bisa lebih baik. Tulis: (a) masalahnya dalam satu kalimat, (b) 4 pertanyaan 'bagaimana jika' yang berbeda tentangnya, (c) satu ide awal yang muncul dari salah satu pertanyaan itu.",sample:"(a) Masalah: Tempat sampah di kelas sering penuh & berantakan sebelum jam istirahat kedua. (b) Bagaimana jika tempat sampah memberi tanda saat hampir penuh? Bagaimana jika sampah dipisah dari awal sehingga volumenya lebih kecil? Bagaimana jika ada jadwal piket khusus 'pengecek sampah' tiap 2 jam? Bagaimana jika kelas menghasilkan jauh lebih sedikit sampah, misalnya melarang bungkus sekali pakai di dalam kelas? (c) Ide awal: dua kotak terpisah, 'kertas' & 'lain-lain', dengan garis penanda 'penuh' di dalamnya, plus piket pengecek jam 9 & jam 11. Dari pertanyaan keempat aku sadar mengurangi sampah dari sumbernya mungkin lebih ampuh daripada mengelola sampah yang sudah ada.",explain:"Jawaban baik: masalah yang jelas & spesifik (bukan 'sekolah kurang bagus'), 4 pertanyaan 'bagaimana jika' yang benar-benar berbeda arah (bukan pengulangan), & satu ide konkret yang jelas berasal dari salah satu pertanyaan.",hint:"Buat tiap pertanyaan menyerang sudut berbeda: teknologi, kebiasaan, aturan, atau menghapus penyebabnya."},

// FASE D — PENALARAN (61-80): rasa ingin tahu produktif, kapan bertanya, jebakan
{n:61,type:"mcq",micro:"Rasa ingin tahu vs menunda kerja",q:"Kadang 'mencari tahu' dipakai sebagai alasan menunda mengerjakan yang penting. Cara sehat:",options:["Selalu utamakan mengikuti setiap rasa penasaran","Sadari bedanya: eksplorasi yang mendukung tujuan vs mengembara tanpa akhir untuk menghindari tugas","Selalu berhenti bertanya & langsung kerja"],answer:1,explain:"Rasa ingin tahu berharga, tapi perlu jujur: apakah ini menggali yang relevan, atau melarikan diri dari pekerjaan?",hint:"Bedakan eksplorasi berguna dari pelarian, atau selalu satu ekstrem?"},
{n:62,type:"mcq",micro:"Terlalu cepat puas",q:"'Rasa ingin tahu yang dangkal' adalah saat...",options:["Kita bertanya terlalu banyak","Kita membaca dari banyak sumber","Kita puas dengan jawaban pertama yang terdengar masuk akal tanpa memeriksa apakah benar"],answer:2,explain:"Ingin tahu sejati memeriksa: 'apakah jawaban ini benar-benar menjelaskan, atau hanya terdengar enak?'",hint:"Puas dengan jawaban yang enak didengar, atau memeriksanya?"},
{n:63,type:"mcq",micro:"Bias 'mencari yang cocok'",q:"Saat penasaran akan sesuatu, jebakan yang perlu diwaspadai:",options:["Hanya mencari informasi yang membenarkan dugaan awal kita & mengabaikan yang bertentangan","Membaca terlalu pelan","Bertanya ke lebih dari satu orang"],answer:0,explain:"Ini 'bias konfirmasi'. Rasa ingin tahu yang jujur sengaja mencari bukti yang bisa membuktikan kita SALAH.",hint:"Cari yang membenarkan dugaan, atau cari yang menantangnya juga?"},
{n:64,type:"tf",micro:"Pertanyaan bisa menyinggung",q:"Benar atau Salah: Semua pertanyaan selalu netral & tidak mungkin menyakiti atau mempermalukan orang lain.",answer:false,explain:"Sebaliknya, pertanyaan tentang tubuh, keluarga, uang, atau kegagalan seseorang bisa menyakitkan. Rasa ingin tahu yang baik memperhatikan perasaan & konteks.",hint:"Selalu netral, atau bisa menyakiti?"},
{n:65,type:"mcq",micro:"Kapan berhenti menggali",q:"Kamu sudah cukup mengeksplorasi sebuah pertanyaan ketika...",options:["Orang lain menyuruh berhenti","Kamu bisa menjelaskannya dengan kata-katamu sendiri & tahu batas apa yang belum kamu ketahui","Kamu lelah"],answer:1,explain:"Tanda paham: bisa menerangkan ke orang lain & sadar 'bagian ini masih belum jelas bagiku'. Itu titik berhenti yang wajar.",hint:"Bisa menjelaskan sendiri + tahu batasnya, atau saat lelah?"},
{n:66,type:"mcq",micro:"Rasa ingin tahu & sumber tepercaya",q:"Saat mencari jawaban dari internet, sikap ingin tahu yang kritis:",options:["Percaya hasil pencarian pertama","Percaya apa pun yang paling banyak dibagikan","Memeriksa siapa yang menulis, apakah ada bukti, & membandingkan beberapa sumber"],answer:2,explain:"Ingin tahu tanpa berpikir kritis mudah tertipu. Keduanya harus jalan bersama.",hint:"Periksa & bandingkan, atau percaya yang pertama?"},
{n:67,type:"mcq",micro:"Pertanyaan yang salah bingkai",q:"Pertanyaan 'Siapa yang harus disalahkan atas nilai jelek kelompok kita?' kurang produktif dibanding...",options:["'Apa yang bisa kita ubah dalam cara kerja kelompok supaya hasil berikutnya lebih baik?'","'Kenapa aku selalu sial?'","'Apakah kelompok lain juga jelek?'"],answer:0,explain:"Pertanyaan 'siapa salah' mencari kambing hitam. Pertanyaan 'apa yang bisa diubah' mencari perbaikan.",hint:"Mencari yang bisa diubah, atau mencari yang disalahkan?"},
{n:68,type:"mcq",micro:"Rasa ingin tahu pada hal yang tidak disukai",q:"Kenapa berharga tetap ingin tahu tentang pendapat yang berbeda dari kita?",options:["Tidak berharga, buang waktu","Karena memahami alasan di baliknya membuat pemikiran kita sendiri lebih kuat & lengkap","Karena kita harus selalu setuju dengan semua orang"],answer:1,explain:"Menutup diri dari pandangan lain membuat kita punya gambaran yang sempit. Memahami bukan berarti menyetujui.",hint:"Memperkuat pemikiran sendiri, atau buang waktu?"},
{n:69,type:"mcq",micro:"Menular",q:"Ketika seorang guru atau teman menunjukkan rasa ingin tahu yang tulus, biasanya...",options:["Orang lain jadi malas berpikir","Tidak ada pengaruh pada orang lain","Orang di sekitarnya ikut lebih berani bertanya & mengeksplorasi"],answer:2,explain:"Rasa ingin tahu menular. Lingkungan yang aman untuk bertanya menumbuhkannya pada semua orang.",hint:"Menular ke sekitar, atau tanpa pengaruh?"},
{n:70,type:"tf",micro:"Tahu banyak = berhenti bertanya?",q:"Benar atau Salah: Semakin banyak seseorang belajar tentang suatu bidang, biasanya semakin sedikit pertanyaan yang ia miliki.",answer:false,explain:"Sebaliknya, biasanya makin dalam belajar, makin banyak pertanyaan baru yang terlihat. Ahli sering paling sadar akan hal yang belum diketahui.",hint:"Makin tahu makin sedikit tanya, atau makin banyak?"},
{n:71,type:"mcq",micro:"Pertanyaan reflektif",q:"Setelah menyelesaikan proyek, pertanyaan ingin tahu yang membantu tumbuh:",options:["'Bagian mana yang berjalan tak terduga? Apa yang akan kucoba berbeda? Apa yang baru kupelajari tentang caraku bekerja?'","'Sudah selesai, tidak perlu dipikir lagi.'","'Kenapa harus ada proyek?'"],answer:0,explain:"Mengarahkan rasa ingin tahu ke pengalaman sendiri (refleksi) mempercepat pembelajaran dari setiap kegiatan.",hint:"Menggali pengalaman sendiri, atau melupakannya?"},
{n:72,type:"mcq",micro:"Batas 'bagaimana jika'",q:"Kapan ide 'bagaimana jika' perlu diuji terhadap kenyataan?",options:["Sebelum satu pun pertanyaan dibuat","Setelah cukup ide terkumpul, saat memilih mana yang akan dibuat/dicoba — cek sumber daya, waktu, & dampaknya","Tidak pernah, biarkan selalu di alam khayalan"],answer:1,explain:"Fase membayangkan & fase menguji itu berbeda. Keduanya perlu, tapi jangan dicampur agar ide tidak mati dini.",hint:"Saat memilih untuk dibuat, atau tidak pernah?"},
{n:73,type:"mcq",micro:"Rasa ingin tahu yang menghargai usaha orang",q:"Bertanya 'kok bisa kepikiran begitu?' kepada teman yang punya ide bagus adalah...",options:["Cara meremehkan idenya","Basa-basi yang tidak berguna","Cara ingin tahu yang juga menghargai & belajar dari proses berpikir orang lain"],answer:2,explain:"Pertanyaan tulus tentang proses orang lain membangun hubungan sekaligus memperkaya cara berpikir kita.",hint:"Menghargai & belajar, atau meremehkan?"},
{n:74,type:"mcq",micro:"Menahan rasa ingin tahu yang merugikan",q:"Rasa penasaran mendorongmu membuka pesan pribadi milik temanmu yang tertinggal terbuka. Sikap yang benar:",options:["Menahan diri & menutupnya/mengembalikannya — rasa ingin tahu tidak membenarkan melanggar privasi","Membacanya karena 'cuma penasaran'","Menceritakan isinya ke orang lain"],answer:0,explain:"Rasa ingin tahu yang sehat berhenti di batas hak & privasi orang lain. Melewatinya bukan lagi kebajikan.",hint:"Berhenti di batas privasi, atau 'cuma penasaran' jadi alasan?"},
{n:75,type:"order",micro:"Menyaring pertanyaan liar",q:"Kamu punya 20 pertanyaan 'bagaimana jika'. Urutkan langkah menyaringnya.",items:["Baca ulang semua & coret yang benar-benar sama","Tandai yang paling membuatmu ingin segera mencari jawabannya","Untuk yang ditandai, cek: mana yang masih mungkin dicoba dengan waktu & alat yang ada","Pilih 1-2 untuk digali serius minggu ini"],answer:[0,1,2,3],explain:"Buang duplikat → tandai yang paling hidup → cek kelayakan → pilih sedikit untuk fokus. Menyaring datang setelah menghasilkan.",hint:"Mengecek kelayakan sebelum atau sesudah menandai yang menarik?"},
{n:76,type:"tf",micro:"Rasa ingin tahu tanpa tindakan",q:"Benar atau Salah: Rasa ingin tahu paling berguna ketika diikuti tindakan, mencari, mencoba, membuat, bukan hanya bertanya-tanya di kepala.",answer:true,explain:"Pertanyaan yang tidak pernah dicari jawabannya jarang mengubah apa pun. Ingin tahu + tindakan = belajar & berkarya.",hint:"Perlu diikuti tindakan, atau cukup di kepala?"},
{n:77,type:"mcq",micro:"Menghormati 'aku tidak tahu'",q:"Saat seseorang menjawab pertanyaanmu dengan 'aku tidak tahu', respons ingin tahu yang baik:",options:["Berhenti & menganggap pertanyaannya buntu","'Tidak apa-apa. Menurutmu ke mana kita bisa cari tahu?'","'Masa tidak tahu sih?'"],answer:1,explain:"'Aku tidak tahu' adalah titik awal, bukan akhir. Bersama mencari jalan mencari tahu.",hint:"Ajak mencari jalan, atau menyalahkan?"},
{n:78,type:"mcq",micro:"Rasa ingin tahu jangka panjang",q:"Orang yang mempertahankan rasa ingin tahu sepanjang hidup cenderung...",options:["Berhenti berkembang setelah dewasa","Merasa hidup membosankan","Terus belajar hal baru, beradaptasi dengan perubahan, & menemukan makna di banyak hal"],answer:2,explain:"Dunia terus berubah. Rasa ingin tahu adalah alat untuk tetap tumbuh & relevan di usia berapa pun.",hint:"Terus tumbuh, atau berhenti berkembang?"},
{n:79,type:"mcq",micro:"Pertanyaan yang menyatukan",q:"Dalam kelompok yang berselisih, pertanyaan ingin tahu yang menenangkan:",options:["'Apa sebenarnya yang sama-sama kita inginkan di sini? Di titik mana kita mulai berbeda?'","'Siapa yang mau mengalah?'","'Kenapa kalian keras kepala?'"],answer:0,explain:"Pertanyaan yang mencari kesamaan & titik pisah membantu kelompok memahami masalah, bukan saling menyerang.",hint:"Mencari kesamaan & titik pisah, atau menyalahkan?"},
{n:80,type:"open",micro:"Rasa ingin tahu yang bertanggung jawab",q:"Jelaskan dengan contohmu sendiri: apa beda antara rasa ingin tahu yang sehat & rasa ingin tahu yang bisa merugikan orang lain atau diri sendiri? Beri minimal dua contoh untuk masing-masing, dan satu aturan pribadi yang akan kamu pakai.",sample:"Rasa ingin tahu sehat: (1) Bertanya ke guru kenapa langit saat senja berwarna oranye, lalu mencari tahu tentang cahaya & atmosfer. (2) Membongkar mainan rusak milikku sendiri untuk memahami cara kerjanya. Rasa ingin tahu yang merugikan: (1) Membaca buku harian adik tanpa izin karena penasaran, ini melanggar privasinya & merusak kepercayaan. (2) Mencoba mencampur bahan kimia pembersih di rumah 'untuk lihat apa yang terjadi', ini bisa berbahaya bagi keselamatan. Bedanya: rasa ingin tahu sehat mencari pemahaman tanpa melanggar hak orang lain atau membahayakan; yang merugikan mengabaikan batas & risiko demi memuaskan penasaran. Aturan pribadiku: sebelum mengikuti rasa penasaran, aku bertanya 'apakah ini aman, dan apakah ini menghormati hak & perasaan orang lain?' Kalau tidak, aku cari cara lain untuk mencari tahu, misalnya bertanya langsung dengan izin.",explain:"Jawaban baik: membedakan dengan jelas berdasarkan (a) menghormati privasi/izin orang lain & (b) keselamatan, memberi 2+2 contoh konkret yang benar-benar sesuai kategorinya, & merumuskan satu aturan pribadi yang bisa dipakai.",hint:"Pikirkan dua garis batas: hak & privasi orang lain, dan keselamatan (diri sendiri & orang lain)."},

// FASE E — TANTANGAN (81-100): skenario, proyek mini, kapstone
{n:81,type:"mcq",micro:"Skenario: kelas membosankan",q:"Sebuah pelajaran terasa membosankan bagimu. Pendekatan paling ingin-tahu:",options:["Menyalahkan guru & topiknya","Cari satu sudut dari topik itu yang benar-benar menarik bagimu & gali dari situ (mis. sejarah di balik rumus)","Menyerah & melamun sepanjang jam"],answer:1,explain:"Rasa ingin tahu bisa diarahkan: hampir semua topik punya 'pintu masuk' yang menarik kalau kita mencarinya.",hint:"Cari pintu masuk yang menarik, atau menyerah?"},
{n:82,type:"mcq",micro:"Skenario: penemuan tak sengaja",q:"Saat percobaan, hasilnya justru berbeda jauh dari dugaanmu. Sikap penemu:",options:["Anggap percobaannya gagal & buang hasilnya","Ubah catatan supaya sesuai dugaan awal","'Ini menarik, kenapa bisa begini? Mungkin ada sesuatu yang belum kupahami.' lalu telusuri"],answer:2,explain:"Hasil tak terduga adalah tambang emas. Banyak penemuan berasal dari 'itu aneh...' bukan 'sesuai harapan'.",hint:"Telusuri keanehannya, atau buang & pura-pura tidak terjadi?"},
{n:83,type:"mcq",micro:"Skenario: pertanyaan tanpa jawaban pasti",q:"Kamu bertanya 'apakah ada kehidupan di planet lain?' & tidak ada jawaban pasti sekarang. Sikap yang matang:",options:["Menikmati menjelajahi kemungkinan & bukti yang ada, sambil menerima bahwa sebagian pertanyaan besar butuh waktu lama","Merasa bertanya itu sia-sia karena tidak ada jawaban pasti","Memilih satu jawaban asal & berhenti"],answer:0,explain:"Sebagian pertanyaan terbaik belum terjawab. Menahan ketidakpastian sambil terus menyelidiki adalah tanda pikiran dewasa.",hint:"Nikmati menjelajah walau belum pasti, atau anggap sia-sia?"},
{n:84,type:"mcq",micro:"Skenario: ide teman lebih baik",q:"Dalam sesi ide kelompok, ide temanmu jelas lebih baik dari idemu. Respons ingin tahu & kolaboratif:",options:["Mencari-cari kelemahan idenya","'Idemu bagus. Bagaimana kalau kita kembangkan bersama, aku punya beberapa tambahan yang mungkin cocok?'","Diam & kesal karena idemu tidak dipakai"],answer:1,explain:"Rasa ingin tahu mengalahkan ego: yang penting ide terbaik menang & kamu ikut membangunnya.",hint:"Kembangkan bersama, atau cari kelemahannya karena kesal?"},
{n:85,type:"tf",micro:"Rasa ingin tahu & keberanian",q:"Benar atau Salah: Mengikuti rasa ingin tahu kadang butuh keberanian, misalnya berani terlihat tidak tahu, berani mencoba hal yang mungkin gagal.",answer:true,explain:"Bertanya di depan kelas, mencoba proyek yang belum tentu berhasil, semuanya butuh keberanian. Itu bagian dari rasa ingin tahu yang hidup.",hint:"Butuh keberanian, atau selalu nyaman?"},
{n:86,type:"mcq",micro:"Skenario: waktu terbatas",q:"Kamu punya 15 menit & 3 pertanyaan besar yang menarik. Pilihan paling bijak:",options:["Coba jawab ketiganya sekilas & tidak tuntas satu pun","Tidak mulai karena waktunya kurang","Pilih satu pertanyaan & telusuri sedalam mungkin dalam 15 menit, catat dua lainnya untuk nanti"],answer:2,explain:"Kedalaman mengalahkan cakupan saat waktu sempit. Menyimpan pertanyaan lain menjaga rasa ingin tahu tetap hidup.",hint:"Satu dalam, atau tiga dangkal?"},
{n:87,type:"mcq",micro:"Skenario: jawaban rumit",q:"Jawaban dari pertanyaanmu ternyata rumit & bertingkat. Sikap ingin tahu:",options:["Pecah jadi bagian-bagian kecil & pahami satu per satu, terima bahwa butuh beberapa kali membaca/bertanya","Menyerah karena terlalu sulit","Ambil versi yang paling sederhana meski keliru"],answer:0,explain:"Pemahaman yang dalam sering datang bertahap. Memecah & mengulang adalah cara kerja yang normal, bukan kegagalan.",hint:"Pecah & pahami bertahap, atau menyerah?"},
{n:88,type:"mcq",micro:"Skenario: memancing rasa ingin tahu orang lain",q:"Kamu ingin adikmu tertarik membaca. Cara yang memakai rasa ingin tahu:",options:["Mengatakan membaca itu 'wajib & penting'","Ceritakan awal kisah yang seru lalu berhenti di bagian menegangkan: 'penasaran? lanjutannya di buku ini'","Menyuruhnya membaca atau dihukum"],answer:1,explain:"Rasa ingin tahu tidak bisa dipaksa, tapi bisa dipancing dengan 'celah' yang bikin orang ingin tahu kelanjutannya.",hint:"Pancing dengan rasa penasaran, atau paksa?"},
{n:89,type:"mcq",micro:"Skenario: bertanya lintas usia",q:"Kakekmu bercerita tentang masa mudanya. Pertanyaan ingin tahu yang menghidupkan percakapan:",options:["'Oh gitu.' lalu diam","'Itu kan sudah lama, Kek.'","'Bagaimana rasanya waktu itu? Apa yang paling berbeda dari sekarang menurut Kakek?'"],answer:2,explain:"Pertanyaan terbuka tentang pengalaman & perasaan membuka cerita yang kaya & mempererat hubungan.",hint:"Pertanyaan terbuka tentang pengalaman, atau menutup percakapan?"},
{n:90,type:"order",micro:"Proyek mini rasa ingin tahu",q:"Urutkan langkah proyek 'selidiki satu pertanyaan selama seminggu'.",items:["Pilih satu pertanyaan yang benar-benar membuatmu penasaran","Tuliskan apa yang sudah kamu duga jawabannya (supaya bisa dibandingkan nanti)","Kumpulkan informasi dari beberapa sumber: amati, coba, tanya, baca","Rangkum apa yang kamu temukan, apa yang mengejutkan, & pertanyaan baru yang muncul"],answer:[0,1,2,3],explain:"Pilih pertanyaan → catat dugaan awal → kumpulkan bukti dari banyak sumber → rangkum + pertanyaan baru. Dugaan awal ditulis agar kita bisa melihat bagaimana pikiran kita berubah.",hint:"Kapan menulis dugaan awal, sebelum atau sesudah mencari?"},
{n:91,type:"mcq",micro:"Skenario: informasi bertentangan",q:"Dua sumber tepercaya memberi jawaban berbeda atas pertanyaanmu. Sikap ingin tahu:",options:["'Menarik, kenapa mereka berbeda? Apa keduanya melihat hal yang berbeda, atau salah satu lebih baru/lebih lengkap?'","Pilih yang paling kamu sukai","Anggap keduanya salah & berhenti"],answer:0,explain:"Perbedaan antar sumber adalah pertanyaan baru, bukan jalan buntu. Menyelidiki 'kenapa berbeda' sering paling mencerahkan.",hint:"Selidiki kenapa berbeda, atau pilih yang disukai?"},
{n:92,type:"tf",micro:"Rasa ingin tahu bisa diarahkan ke dalam diri",q:"Benar atau Salah: Rasa ingin tahu hanya bisa diarahkan pada dunia luar, tidak pada pikiran atau reaksi diri sendiri.",answer:false,explain:"Sebaliknya, rasa ingin tahu juga bisa diarahkan ke dalam ('kenapa aku bereaksi marah tadi?'). Menyelidiki pikiran & reaksi sendiri tanpa menghakimi adalah dasar kecerdasan emosi.",hint:"Bisa diarahkan ke dalam diri, atau hanya ke luar?"},
{n:93,type:"mcq",micro:"Skenario: proyek gagal",q:"Proyek yang kamu buat dari sebuah ide 'bagaimana jika' ternyata tidak berhasil. Cara ingin tahu memandangnya:",options:["Sembunyikan proyeknya & jangan cerita ke siapa pun","'Bagian mana yang tidak jalan & kenapa? Apa yang tetap berhasil? Apa yang kupelajari untuk ide berikutnya?'","'Berarti aku tidak berbakat.'"],answer:1,explain:"Kegagalan yang diselidiki dengan rasa ingin tahu berubah jadi data berharga. Kegagalan yang dihindari tidak mengajari apa-apa.",hint:"Selidiki apa yang bisa dipelajari, atau simpulkan 'tidak berbakat'?"},
{n:94,type:"mcq",micro:"Skenario: pertanyaan yang mengubah rencana",q:"Di tengah proyek, muncul pertanyaan 'apakah kita menyelesaikan masalah yang benar?' Sikap yang tepat:",options:["Abaikan karena rencana sudah dibuat","Tunda pertanyaan itu sampai proyek selesai","Berhenti sejenak & pertimbangkan serius, meski berarti mengubah rencana, lebih baik daripada menyelesaikan hal yang salah dengan rapi"],answer:2,explain:"Pertanyaan mendasar yang muncul di tengah jalan kadang paling penting. Berani meninjau ulang adalah tanda rasa ingin tahu yang jujur.",hint:"Tinjau ulang serius, atau abaikan demi rencana?"},
{n:95,type:"tf",micro:"Rasa ingin tahu & rendah hati",q:"Benar atau Salah: Rasa ingin tahu yang tulus berjalan bersama kerendahan hati, kesediaan mengakui 'aku mungkin salah' atau 'aku belum tahu'.",answer:true,explain:"Kalau kita merasa sudah tahu segalanya, tidak ada ruang untuk bertanya. Kerendahan hati membuka pintu belajar.",hint:"Berjalan dengan kerendahan hati, atau dengan rasa selalu benar?"},
{n:96,type:"mcq",micro:"Skenario: memilih topik proyek bebas",q:"Kamu diberi proyek bebas. Cara memilih topik yang paling menghidupkan rasa ingin tahu:",options:["Pilih pertanyaan yang sudah lama mengganjal di kepalamu & benar-benar ingin kamu ketahui jawabannya","Pilih yang paling mudah dapat nilai bagus","Pilih yang sama dengan teman supaya bisa mencontek"],answer:0,explain:"Proyek yang lahir dari rasa penasaran asli hampir selalu lebih dalam, lebih bertahan, & lebih memuaskan.",hint:"Pertanyaan yang benar-benar mengganjal, atau yang paling mudah?"},
{n:97,type:"mcq",micro:"Skenario: menjaga rasa ingin tahu tetap etis",q:"Rasa penasaranmu tentang cara kerja akun media sosial temanmu mendorongmu ingin menebak kata sandinya. Sikap benar:",options:["Minta orang lain yang menebaknya","Berhenti, itu melanggar batas & bisa merugikan; kalau ingin tahu cara kerja keamanan akun, pelajari dari sumber umum","Coba tebak 'iseng saja'"],answer:1,explain:"Rasa ingin tahu tentang sistem itu baik, tapi tidak boleh dipuaskan dengan melanggar akun atau privasi orang.",hint:"Pelajari dari sumber umum, atau langgar akun 'iseng'?"},
{n:98,type:"mcq",micro:"Skenario: mengajukan pertanyaan ke dunia",q:"Kamu memperhatikan banyak lansia di lingkunganmu kesulitan menyeberang jalan. Pertanyaan yang bisa jadi awal karya nyata:",options:["'Kenapa mereka tidak di rumah saja?'","'Bukan urusanku.'","'Kenapa penyeberangan di sini sulit bagi mereka? Apa yang paling menghambat, & apa yang bisa diubah oleh warga sendiri?'"],answer:2,explain:"Rasa ingin tahu yang diarahkan pada masalah nyata di sekitar kita adalah awal dari kontribusi & inovasi sosial.",hint:"Menggali penyebab & yang bisa diubah, atau menyalahkan mereka?"},
{n:99,type:"mcq",micro:"Menilai kualitas pertanyaan",q:"Ciri 'pertanyaan yang bagus' untuk memancing ide:",options:["Terbuka, menantang sebuah asumsi, & membuatmu ingin segera mencari atau mencoba sesuatu","Bisa dijawab 'ya' atau 'tidak' dengan cepat","Sudah kamu tahu jawabannya"],answer:0,explain:"Pertanyaan terbaik terasa 'membuka' — ia memperluas kemungkinan, bukan menutupnya.",hint:"Terbuka & menantang asumsi, atau jawaban ya/tidak yang sudah diketahui?"},
{n:100,type:"open",micro:"Kapstone: hidup dengan rasa ingin tahu",q:"Rancang 'kebiasaan rasa ingin tahu' pribadi untuk sebulan ke depan. Sertakan: (a) satu kebiasaan harian kecil, (b) satu pertanyaan besar yang ingin kamu selidiki bulan ini & langkah pertamanya, (c) satu aturan agar rasa ingin tahumu tetap menghormati orang lain, (d) cara kamu akan tahu di akhir bulan bahwa kebiasaan ini berhasil.",sample:"(a) Kebiasaan harian: setiap malam menulis di buku catatan 'satu hal yang membuatku penasaran hari ini' plus satu pertanyaan tentangnya, target minimal 20 hari dari 30. (b) Pertanyaan besar: 'Kenapa sungai di dekat rumahku airnya berubah keruh beberapa tahun terakhir?' Langkah pertama: mengamati & memotret kondisi sungai di tiga titik minggu ini, lalu bertanya ke tetangga yang sudah lama tinggal di sana tentang perubahan yang mereka ingat. (c) Aturan menghormati orang lain: aku hanya akan menyelidiki hal yang menyangkut orang lain dengan bertanya langsung & meminta izin; aku tidak akan mengorek informasi pribadi atau masuk ke area terlarang demi rasa penasaran. (d) Ukuran keberhasilan: di akhir bulan aku punya minimal 20 catatan pertanyaan, sudah menelusuri pertanyaan besar sampai bisa menjelaskan kemungkinan penyebabnya dengan kata-kataku sendiri, & bisa menyebut minimal 3 hal baru yang kupelajari yang tidak kuketahui di awal bulan.",explain:"Jawaban baik: kebiasaan harian yang kecil & realistis (bisa benar-benar dilakukan), pertanyaan besar yang spesifik dengan langkah pertama yang konkret, aturan etika yang jelas tentang privasi/izin/keselamatan, & ukuran keberhasilan yang bisa diperiksa (bukan 'merasa lebih ingin tahu' tapi sesuatu yang bisa dihitung atau ditunjukkan).",hint:"Buat tiap bagian cukup kecil & jelas sehingga kamu benar-benar bisa melakukannya & memeriksanya di akhir bulan."},
];
